def copy_existing_answers(apps, schema_editor):
    """
    Each zone held one answer. Keep it, filed under the barangay of the
    person who gave it. An answer from someone with no barangay can't be
    placed, but the zone-level summary still shows it.
    """
    HazardZone = apps.get_model('hazards', 'HazardZone')
    HazardVerification = apps.get_model('hazards', 'HazardVerification')
    zones = (
        HazardZone.objects
        .filter(verification_status__in=['Confirmed', 'Disputed'], verified_by__assigned_barangay__isnull=False)
        .select_related('verified_by')
    )
    for z in zones:
        HazardVerification.objects.get_or_create(
            hazard_zone=z,
            barangay_id=z.verified_by.assigned_barangay_id,
            defaults={
                'status': z.verification_status,
                'note': z.verification_note or '',
                'answered_by': z.verified_by,
                'answered_at': z.verified_at or z.activated_at,
            },
        )


